import numpy as np,pandas as pd,glob
dec=10
def prep(f):
    d=pd.read_csv(f).values; n=len(d)//dec*dec
    return d[1:n+1].reshape(-1,dec,6).mean(1)
def build(fs,na):
    Xs=[];Ys=[]
    for f in fs:
        m=prep(f); P,Q,V,th,Vs=m[:,1]-m[0,1],m[:,2]-m[0,2],m[:,3]-m[0,3],m[:,4],m[:,5]-m[0,3]
        dth=np.r_[0,np.diff(th)]; Y=np.c_[P,Q]; U=np.c_[V,dth,Vs]
        for k in range(na,len(m)):
            Xs.append(np.r_[Y[k-na:k][::-1].ravel(),U[k-na+1:k+1][::-1].ravel()]);Ys.append(Y[k])
    return np.array(Xs),np.array(Ys)
